// Brique « enregistrer » – contrôle de la demande de validation.
// On n'enregistre que le texte d'un BROUILLON existant (créé par « rédiger ») : le texte validé est celui que
// le soignant a relu et éventuellement corrigé, rattaché à ce brouillon.
const e = $input.first().json ?? {};
const id = String(e.brouillon_id ?? '');
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id)) throw new Error('brouillon_id invalide');
const texte = String(e.texte ?? '').trim();
if (!texte || texte.length > 20000) throw new Error('texte vide ou trop long (20 000 caractères au maximum)');
return [{ json: { brouillon_id: id, texte, valide_par: String(e.valide_par ?? 'soignant (non identifié)').slice(0, 80), soignant_id: String(e.soignant_id ?? '').slice(0, 40) } }];

// Brique « enregistrer » – résultat de la validation, et événement d'audit associé.
const c = $('Contrôler la validation').first().json;
const v = $('Valider le brouillon').first().json;

const resultat = v.validation_id
  ? {
      ok: true,
      validation_id: v.validation_id,
      brouillon_id: c.brouillon_id,
      patient_id: v.patient_id,
      mode: v.mode,
      action: v.action,
      modifiee: v.modifiee,
      texte: c.texte,
      valide_par: c.valide_par,
      soignant_id: c.soignant_id,
    }
  : { ok: false, erreur: 'Brouillon introuvable ou déjà validé.', brouillon_id: c.brouillon_id };

return [
  {
    json: {
      ...resultat,
      evenement_journal: {
        evenement: resultat.ok ? 'validation' : 'validation_refusee',
        patient_id: resultat.patient_id ?? null,
        mode: resultat.mode ?? null,
        action: resultat.action ?? null,
        details: { brouillon_id: c.brouillon_id, modifiee: resultat.modifiee ?? null, valide_par: c.valide_par, soignant_id: c.soignant_id || null },
      },
    },
  },
];

// Brique « enregistrer » – sortie : le résultat de la validation (sans l'événement de journal).
const { evenement_journal, ...resultat } = $('Résultat de la validation').first().json;
return [{ json: resultat }];
